=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md per microarchitecture.md.
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer  AW     = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer  CW     = $clog2(DEPTH + 1);
    localparam integer  LAST_I = DEPTH - 1;
    localparam [AW-1:0] LAST   = LAST_I[AW-1:0];
    localparam [CW-1:0] FULL_C = DEPTH[CW-1:0];

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // State registers and their next values.
    reg [AW-1:0] wr_ptr_q;
    reg [AW-1:0] wr_ptr_d;
    reg [AW-1:0] rd_ptr_q;
    reg [AW-1:0] rd_ptr_d;
    reg [CW-1:0] count_q;
    reg [CW-1:0] count_d;

    wire wr_acc;
    wire rd_acc;

    assign full    = (count_q == FULL_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign rd_data = mem[rd_ptr_q];

    // The flags gate the requests: overflow and underflow policy.
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // Next-state logic.
    always @(*) begin
        wr_ptr_d = wr_ptr_q;
        rd_ptr_d = rd_ptr_q;
        count_d  = count_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = {AW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + 1'b1;
            end
        end
        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = {AW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + 1'b1;
            end
        end
        if (wr_acc && !rd_acc) begin
            count_d = count_q + 1'b1;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - 1'b1;
        end
    end

    // State registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {AW{1'b0}};
            rd_ptr_q <= {AW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage write, only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    localparam integer FW = CW + 1;

    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*) assume (f_addr <= LAST);

    wire [FW-1:0] f_dep    = DEPTH;
    wire [FW-1:0] f_rd     = {{(FW-AW){1'b0}}, rd_ptr_q};
    wire [FW-1:0] f_ad     = {{(FW-AW){1'b0}}, f_addr};
    wire [FW-1:0] f_cnt    = {1'b0, count_q};
    wire [FW-1:0] f_sum    = f_rd + f_cnt;
    wire [FW-1:0] f_wexp   = (f_sum >= f_dep) ? (f_sum - f_dep) : f_sum;
    wire [FW-1:0] f_off    = (f_ad >= f_rd) ? (f_ad - f_rd) : ((f_ad + f_dep) - f_rd);
    wire          f_in_use = (f_off < f_cnt);

    // State invariants.
    always @(*) begin
        if (f_past_valid) begin
            assert (count_q <= FULL_C);
            assert (full  == (count_q == FULL_C));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (wr_ptr_q <= LAST);
            assert (rd_ptr_q <= LAST);
            assert (wr_ptr_q == f_wexp[AW-1:0]);
            if (!empty && (rd_ptr_q == f_addr)) assert (rd_data == mem[f_addr]);
        end
    end

    // Transition properties.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == 0);
                assert (wr_ptr_q == 0);
                assert (rd_ptr_q == 0);
                assert (empty);
                assert (!full);
            end else begin
                assert (count_q == $past(count_q) + $past(wr_acc) - $past(rd_acc));
                if ($past(full)) begin
                    assert (wr_ptr_q == $past(wr_ptr_q));
                    assert (mem[f_addr] == $past(mem[f_addr]));
                end
                if ($past(empty)) begin
                    assert (rd_ptr_q == $past(rd_ptr_q));
                end
                if ($past(wr_acc) && ($past(wr_ptr_q) == f_addr)) begin
                    assert (mem[f_addr] == $past(wr_data));
                end
            end
            if ($past(f_in_use)) begin
                assert (mem[f_addr] == $past(mem[f_addr]));
            end
        end
    end

    // Covers: the FIFO fills, returns to empty, and wraps.
    reg f_seen_full = 1'b0;
    always @(posedge clk) begin
        if (!rst_n) f_seen_full <= 1'b0;
        else if (full) f_seen_full <= 1'b1;
    end

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (f_seen_full && empty);
            cover (wr_acc && rd_acc);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            cover ($past(rst_n) && $past(wr_acc) && ($past(wr_ptr_q) == LAST));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
