// Self-checking testbench for sync_fifo: two configurations, one reference
// queue each, checks on every cycle, coverage goals, one verdict line.
`timescale 1ns/1ps

module sync_fifo_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg         rst_n;
    reg         wr_en;
    reg         rd_en;
    reg  [11:0] wr_data;
    reg         done;
    reg  [11:0] dval;
    reg  [31:0] rv;
    reg  [31:0] passed;
    reg  [31:0] failed;
    reg  [8*64-1:0] nonce;
    integer     found;

    // DUT 0: DEPTH 8, WIDTH 8.
    wire        full0;
    wire        empty0;
    wire [3:0]  count0;
    wire [7:0]  rd_data0;
    wire [31:0] passed0;
    wire [31:0] failed0;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) dut0 (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[7:0]), .full(full0),
        .rd_en(rd_en), .rd_data(rd_data0), .empty(empty0),
        .count(count0)
    );

    sync_fifo_sb #(.DEPTH(8), .WIDTH(8)) sb0 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data(wr_data[7:0]), .full(full0), .empty(empty0),
        .count(count0), .rd_data(rd_data0), .done(done),
        .passed(passed0), .failed(failed0)
    );

    // DUT 1: DEPTH 5 (not a power of two), WIDTH 12.
    wire        full1;
    wire        empty1;
    wire [2:0]  count1;
    wire [11:0] rd_data1;
    wire [31:0] passed1;
    wire [31:0] failed1;

    sync_fifo #(.DEPTH(5), .WIDTH(12)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full1),
        .rd_en(rd_en), .rd_data(rd_data1), .empty(empty1),
        .count(count1)
    );

    sync_fifo_sb #(.DEPTH(5), .WIDTH(12)) sb1 (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
        .wr_data(wr_data), .full(full1), .empty(empty1),
        .count(count1), .rd_data(rd_data1), .done(done),
        .passed(passed1), .failed(failed1)
    );

    // Inputs change on the falling edge and are sampled on the next rising edge.
    task drive(input r, input w, input rd, input [11:0] d);
        begin
            @(negedge clk);
            rst_n   = r;
            wr_en   = w;
            rd_en   = rd;
            wr_data = d;
        end
    endtask

    task dseq(input r, input w, input rd);
        begin
            drive(r, w, rd, dval);
            dval = dval + 12'd1;
        end
    endtask

    task rand_phase(input integer n, input [7:0] wthr, input [7:0] rthr);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                rv = $random;
                drive(1'b1, (rv[7:0] < wthr), (rv[15:8] < rthr), rv[27:16]);
            end
        end
    endtask

    initial begin
        nonce   = {(8*64){1'b0}};
        found   = $value$plusargs("nirmaan_nonce=%s", nonce);
        rst_n   = 1'b0;
        wr_en   = 1'b1;   // requests during reset must be ignored
        rd_en   = 1'b1;
        wr_data = 12'hA5A;
        done    = 1'b0;
        dval    = 12'h001;
        passed  = 32'd0;
        failed  = 32'd0;

        // Reset with requests active.
        dseq(1'b0, 1'b1, 1'b1);
        dseq(1'b0, 1'b1, 1'b1);

        // Read while empty.
        dseq(1'b1, 1'b0, 1'b1);
        dseq(1'b1, 1'b0, 1'b1);

        // Write and read together when empty: only the write is accepted.
        dseq(1'b1, 1'b1, 1'b1);

        // Fill to full, then writes while full.
        repeat (10) dseq(1'b1, 1'b1, 1'b0);

        // Write and read together when full: only the read is accepted.
        dseq(1'b1, 1'b1, 1'b1);

        // Write and read together in between.
        repeat (3) dseq(1'b1, 1'b1, 1'b1);

        // Drain to empty, then reads while empty.
        repeat (12) dseq(1'b1, 1'b0, 1'b1);

        // Random traffic with stalls on both sides.
        rand_phase(400, 8'd200, 8'd60);
        rand_phase(400, 8'd60,  8'd200);
        rand_phase(600, 8'd128, 8'd128);

        // Reset during traffic, with entries held.
        repeat (4) dseq(1'b1, 1'b1, 1'b0);
        dseq(1'b0, 1'b1, 1'b1);
        dseq(1'b0, 1'b1, 1'b1);

        rand_phase(300, 8'd200, 8'd60);
        rand_phase(300, 8'd60,  8'd200);
        rand_phase(300, 8'd128, 8'd128);

        drive(1'b1, 1'b0, 1'b0, 12'd0);
        @(negedge clk);
        done = 1'b1;
        @(negedge clk);
        @(negedge clk);
        #1;
        passed = passed0 + passed1;
        failed = failed0 + failed1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

// Reference-queue scoreboard for one sync_fifo instance.
module sync_fifo_sb #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire                       rd_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       full,
    input  wire                       empty,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire [WIDTH-1:0]           rd_data,
    input  wire                       done,
    output wire [31:0]                passed,
    output wire [31:0]                failed
);

    localparam integer  AW     = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer  CW     = $clog2(DEPTH + 1);
    localparam integer  LAST_I = DEPTH - 1;
    localparam integer  ONE_I  = 1;
    localparam [AW-1:0] LAST   = LAST_I[AW-1:0];
    localparam [CW-1:0] FULL_C = DEPTH[CW-1:0];
    localparam [CW-1:0] ONE_C  = ONE_I[CW-1:0];
    localparam [CW-1:0] ZERO_C = {CW{1'b0}};

    reg [WIDTH-1:0] q [0:DEPTH-1];
    reg [AW-1:0]    head;
    reg [AW-1:0]    tail;
    reg [CW-1:0]    mcnt;
    reg             seen_rst = 1'b0;
    reg             cov_done = 1'b0;
    reg             acc_w;
    reg             acc_r;

    reg [31:0] n_pass = 32'd0;
    reg [31:0] n_fail = 32'd0;
    assign passed = n_pass;
    assign failed = n_fail;

    reg [31:0] c_full        = 32'd0;
    reg [31:0] c_wr_full     = 32'd0;
    reg [31:0] c_drain       = 32'd0;
    reg [31:0] c_rd_empty    = 32'd0;
    reg [31:0] c_wr_rd_empty = 32'd0;
    reg [31:0] c_wr_rd_full  = 32'd0;
    reg [31:0] c_wr_rd_mid   = 32'd0;
    reg [31:0] c_wrap_w      = 32'd0;
    reg [31:0] c_wrap_r      = 32'd0;
    reg [31:0] c_rst_traffic = 32'd0;

    // Model update on the rising edge, from the state before the edge.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (seen_rst && (mcnt != ZERO_C)) c_rst_traffic <= c_rst_traffic + 32'd1;
            head     <= {AW{1'b0}};
            tail     <= {AW{1'b0}};
            mcnt     <= ZERO_C;
            seen_rst <= 1'b1;
        end else if (seen_rst) begin
            acc_w = wr_en && (mcnt != FULL_C);
            acc_r = rd_en && (mcnt != ZERO_C);

            if (mcnt == FULL_C) c_full <= c_full + 32'd1;
            if (wr_en && !rd_en && (mcnt == FULL_C)) c_wr_full <= c_wr_full + 32'd1;
            if (acc_r && !acc_w && (mcnt == ONE_C)) c_drain <= c_drain + 32'd1;
            if (rd_en && !wr_en && (mcnt == ZERO_C)) c_rd_empty <= c_rd_empty + 32'd1;
            if (wr_en && rd_en && (mcnt == ZERO_C)) c_wr_rd_empty <= c_wr_rd_empty + 32'd1;
            if (wr_en && rd_en && (mcnt == FULL_C)) c_wr_rd_full <= c_wr_rd_full + 32'd1;
            if (wr_en && rd_en && (mcnt != ZERO_C) && (mcnt != FULL_C)) c_wr_rd_mid <= c_wr_rd_mid + 32'd1;
            if (acc_w && (tail == LAST)) c_wrap_w <= c_wrap_w + 32'd1;
            if (acc_r && (head == LAST)) c_wrap_r <= c_wrap_r + 32'd1;

            if (acc_w) begin
                q[tail] <= wr_data;
                tail    <= (tail == LAST) ? {AW{1'b0}} : (tail + 1'b1);
            end
            if (acc_r) begin
                head <= (head == LAST) ? {AW{1'b0}} : (head + 1'b1);
            end
            if (acc_w && !acc_r) begin
                mcnt <= mcnt + 1'b1;
            end else if (acc_r && !acc_w) begin
                mcnt <= mcnt - 1'b1;
            end
        end
    end

    task check(input ok, input [3:0] id);
        begin
            if (ok) begin
                n_pass = n_pass + 32'd1;
            end else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH=%0d WIDTH=%0d: check %0d failed at %0t (model count %0d)",
                       DEPTH, WIDTH, id, $time, mcnt);
            end
        end
    endtask

    // Outputs depend only on state, so sampling on the falling edge is race-free.
    // Check ids: 0 full, 1 empty, 2 count, 3 rd_data, 4..13 coverage goals.
    always @(negedge clk) begin
        if (seen_rst) begin
            check(full  === (mcnt == FULL_C), 4'd0);
            check(empty === (mcnt == ZERO_C), 4'd1);
            check(count === mcnt, 4'd2);
            if (mcnt != ZERO_C) check(rd_data === q[head], 4'd3);
            if (done && !cov_done) begin
                cov_done = 1'b1;
                check(c_full        != 32'd0, 4'd4);
                check(c_wr_full     != 32'd0, 4'd5);
                check(c_drain       != 32'd0, 4'd6);
                check(c_rd_empty    != 32'd0, 4'd7);
                check(c_wr_rd_empty != 32'd0, 4'd8);
                check(c_wr_rd_full  != 32'd0, 4'd9);
                check(c_wr_rd_mid   != 32'd0, 4'd10);
                check(c_wrap_w      != 32'd0, 4'd11);
                check(c_wrap_r      != 32'd0, 4'd12);
                check(c_rst_traffic != 32'd0, 4'd13);
            end
        end
    end

endmodule
